begin;
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claim.role','authenticated',true);
insert into branches(id,code,name) values('ed100000-0000-0000-0000-000000000001','SGC-A','SGC sucursal ficticia'),('ed100000-0000-0000-0000-000000000002','SGC-B','SGC sucursal ajena');
insert into auth.users(id,email) values('ed200000-0000-0000-0000-000000000001','sgc-owner@example.invalid'),('ed200000-0000-0000-0000-000000000002','sgc-review@example.invalid'),('ed200000-0000-0000-0000-000000000003','sgc-reader@example.invalid');
insert into profiles(id,full_name,branch_id,active) select v.id,v.name,'ed100000-0000-0000-0000-000000000001',true from(values('ed200000-0000-0000-0000-000000000001'::uuid,'Responsable ficticio'),('ed200000-0000-0000-0000-000000000002'::uuid,'Revisor ficticio'),('ed200000-0000-0000-0000-000000000003'::uuid,'Lector ficticio'))v(id,name);
insert into roles(code,name) values('SGC_TEST_OP','Operador acotado SGC'),('SGC_TEST_READ','Lector SGC');
insert into role_permissions select r.id,p.permission_code from roles r cross join app_permissions p where r.code='SGC_TEST_OP' and p.permission_code in ('QUALITY_VIEW','QUALITY_WRITE','QUALITY_DAILY_REVIEW','WORK_AGENDA_VIEW','WORK_AGENDA_WRITE','WORK_AGENDA_MANAGE','DOCUMENTS_VIEW','DOCUMENTS_WRITE') or r.code='SGC_TEST_READ' and p.permission_code='QUALITY_VIEW';
insert into work_area_roles select id,'CALIDAD',true,true from roles where code='SGC_TEST_OP';
insert into user_roles(user_id,role_id,branch_id) select v.id,r.id,'ed100000-0000-0000-0000-000000000001' from(values('ed200000-0000-0000-0000-000000000001'::uuid,'SGC_TEST_OP'),('ed200000-0000-0000-0000-000000000002'::uuid,'SGC_TEST_OP'),('ed200000-0000-0000-0000-000000000003'::uuid,'SGC_TEST_READ'))v(id,code)join roles r on r.code=v.code;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
create function pg_temp.denied(stmt text,label text) returns void language plpgsql as $$begin begin execute stmt;exception when others then raise notice 'PASS %',label;return;end;raise exception 'FAIL unexpectedly allowed %',label;end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select sgc_project_action('CREATE','{"branch_id":"ed100000-0000-0000-0000-000000000002","reviewer_id":"ed200000-0000-0000-0000-000000000002"}')$q$,'SGC creator cannot use an unauthorized branch');
select pg_temp.denied($q$select sgc_project_action('CREATE','{"branch_id":"ed100000-0000-0000-0000-000000000001","reviewer_id":"ed200000-0000-0000-0000-000000000001"}')$q$,'project requires independent reviewer');
select sgc_project_action('CREATE',jsonb_build_object('project_code','SGC-TEST','title','Proyecto ficticio','scope','Alcance ficticio de pruebas','branch_id','ed100000-0000-0000-0000-000000000001','reviewer_id','ed200000-0000-0000-0000-000000000002','start_date',current_date,'target_date',current_date+730));
select pg_temp.ok((select count(*)=44 from sgc_steps where project_id=(select id from sgc_projects where project_code='SGC-TEST')),'project creates exactly 44 steps from frozen blueprint');
select pg_temp.ok((select count(*)=12 from sgc_gates where project_id=(select id from sgc_projects where project_code='SGC-TEST')),'project creates twelve ordered gates');
select pg_temp.denied($q$update sgc_steps set status='VERIFICADO'$q$,'direct client writes cannot bypass verification');
select pg_temp.denied($q$update sgc_projects set definition='{}'$q$,'client cannot change frozen project requirements');
select pg_temp.denied($q$delete from sgc_history$q$,'client cannot erase project audit');
select sgc_project_action('REGISTER_DOCUMENT',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'document_code','SGC-TEST-DOC','title','Synthetic deliverable','version','1','document_type','PROCEDIMIENTO','source_path','https://example.invalid/approved-fixture'));
select pg_temp.ok((select status='BORRADOR' from document_register where document_code='SGC-TEST-DOC'),'document intake never auto approves');
select pg_temp.denied($q$select sgc_project_action('SUBMIT',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'evidence','Ref','checklist',(select jsonb_agg(jsonb_build_object('label',x->>'label','done',true)) from jsonb_array_elements(checklist)x),'documents','[]'::jsonb) from sgc_steps where step_code='GOV1'))$q$,'required approved document cannot be omitted');
select pg_temp.denied($q$select sgc_project_action('REQUEST_NA',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'evidence','Exclusion','checklist',checklist) from sgc_steps where step_code='GOV1'))$q$,'mandatory implementation steps cannot be excluded');
select pg_temp.denied($q$select sgc_project_action('GATE_SUBMIT',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'evidence','Gate') from sgc_gates where gate_code='G2'))$q$,'gate cannot skip earlier gates');
reset role;
-- Exercise the existing real approval workflow using synthetic local actors.
select set_config('request.jwt.claim.sub','f9200000-0000-0000-0000-000000000001',true);
insert into user_roles(user_id,role_id,branch_id) select u.id,r.id,'ed100000-0000-0000-0000-000000000001' from (values('ed200000-0000-0000-0000-000000000001'::uuid),('ed200000-0000-0000-0000-000000000002'::uuid))u(id) cross join roles r where r.code='CALIDAD';
set local role authenticated;
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
select request_document_approval((select id from document_register where document_code='SGC-TEST-DOC'),'Approve synthetic procedure for isolated project tests');
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000002',true);
select decide_approval_request((select approval_request_id from document_register where document_code='SGC-TEST-DOC'),'APROBAR','Reviewed synthetic evidence','I reviewed the local fixture');
select execute_approved_action((select approval_request_id from document_register where document_code='SGC-TEST-DOC'));
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
create function pg_temp.submit_step(code text) returns void language plpgsql as $$declare st sgc_steps%rowtype;dr document_register%rowtype;begin select * into st from sgc_steps where step_code=code and project_id=(select id from sgc_projects where project_code='SGC-TEST');select * into dr from document_register where document_code='SGC-TEST-DOC';perform sgc_project_action('SUBMIT',jsonb_build_object('project_id',st.project_id,'id',st.id,'revision',st.revision,'evidence','Synthetic reference; isolated test only','notes','SOLICITUD_NO_APLICA','checklist',(select jsonb_agg(jsonb_build_object('label',x->>'label','done',true)) from jsonb_array_elements(st.checklist)x),'documents',case when(st.definition->>'document_required')::boolean then jsonb_build_array(jsonb_build_object('id',dr.id,'version',dr.version,'source_path',dr.source_path))else '[]'::jsonb end,'period_start',current_date-250,'period_end',(now() at time zone 'America/Santo_Domingo')::date));end$$;
select pg_temp.submit_step('GOV1');
select pg_temp.denied($q$select sgc_project_action('VERIFY',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'note','Own review') from sgc_steps where step_code='GOV1'))$q$,'executor cannot verify own step');
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000002',true);
select sgc_project_action('VERIFY',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'note','Independent synthetic review') from sgc_steps where step_code='GOV1'));
select pg_temp.ok((select status='VERIFICADO' and not requested_na from sgc_steps where step_code='GOV1'),'magic text cannot forge no-aplica on a mandatory step');
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
select pg_temp.denied($q$select sgc_project_action('SAVE',(select jsonb_build_object('project_id',project_id,'id',id,'revision',1,'checklist',checklist) from sgc_steps where step_code='GOV1'))$q$,'stale step revisions rejected');
reset role;
update document_register set version='2' where document_code='SGC-TEST-DOC';
set local role authenticated;
select pg_temp.ok((sgc_project_action('CHECK',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST')))->'invalid_steps') ? 'GOV1','changed document version invalidates current evidence health');
select pg_temp.denied($q$select sgc_project_action('GATE_SUBMIT',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'evidence','Gate') from sgc_gates where gate_code='G1'))$q$,'outdated document blocks gate submission');
reset role;update document_register set version='1' where document_code='SGC-TEST-DOC';set local role authenticated;
select sgc_project_action('REQUEST_NA',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'evidence','No real NC occurred; absence justified in local fixture','checklist',checklist) from sgc_steps where step_code='IMP5'));
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000002',true);
select sgc_project_action('VERIFY',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'note','Scoped exclusion reviewed') from sgc_steps where step_code='IMP5'));
select pg_temp.ok((select status='NO_APLICA' from sgc_steps where step_code='IMP5'),'optional exclusion requires independent review');
-- Complete the entire synthetic project, enforcing phase and gate order.
do $$declare gt sgc_gates%rowtype;st sgc_steps%rowtype;begin
 for gt in select * from sgc_gates where project_id=(select id from sgc_projects where project_code='SGC-TEST') order by substring(gate_code from 2)::int loop
  for st in select * from sgc_steps where project_id=gt.project_id and(gt.definition->'steps') ? step_code order by step_code loop
   if st.status in ('VERIFICADO','NO_APLICA') then continue;end if;
   perform set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
   if st.step_code='VER1' then perform pg_temp.denied(format('select sgc_project_action(''SUBMIT'',%L::jsonb)',jsonb_build_object('project_id',st.project_id,'id',st.id,'revision',st.revision,'evidence','Too short','checklist',(select jsonb_agg(jsonb_build_object('label',x->>'label','done',true)) from jsonb_array_elements(st.checklist)x),'documents','[]'::jsonb,'period_start',current_date-15,'period_end',(now() at time zone 'America/Santo_Domingo')::date)),'six calendar months cannot be replaced by a short period');end if;
   perform pg_temp.submit_step(st.step_code);perform set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000002',true);
   select * into st from sgc_steps where id=st.id;perform sgc_project_action('VERIFY',jsonb_build_object('project_id',st.project_id,'id',st.id,'revision',st.revision,'note','Independent fixture review'));
  end loop;
  perform set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);select * into gt from sgc_gates where id=gt.id;
  perform sgc_project_action('GATE_SUBMIT',jsonb_build_object('project_id',gt.project_id,'id',gt.id,'revision',gt.revision,'evidence','Synthetic committee decision file'));
  perform set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000002',true);select * into gt from sgc_gates where id=gt.id;
  perform sgc_project_action('GATE_APPROVE',jsonb_build_object('project_id',gt.project_id,'id',gt.id,'revision',gt.revision,'note','Committee evidence reviewed'));
 end loop;
end$$;
select pg_temp.ok((select count(*)=12 from sgc_gates where status='APROBADA'),'all twelve gates can complete through governed sequence');
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000001',true);
select sgc_project_action('CLOSE_PROJECT',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'note','Internal delivery, no external accreditation claimed'));
select pg_temp.ok((select status='CERRADO_VERIFICADO' from sgc_projects where project_code='SGC-TEST'),'project can close after independently approved gates');
select sgc_project_action('REOPEN_PROJECT',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'note','Changed source requires correction'));
select sgc_project_action('REOPEN_STEP',(select jsonb_build_object('project_id',project_id,'id',id,'revision',revision,'note','Revisit governance evidence') from sgc_steps where step_code='GOV1'));
select pg_temp.ok((select count(*)=0 from sgc_gates where status='APROBADA'),'reopening early step invalidates all affected downstream gates');
select pg_temp.ok((select count(*)>100 from sgc_history),'full project decisions preserve immutable history');
select sgc_project_action('ADD_STEP',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'phase_code','F1','step_code','X-ALCANCE','title','Paso específico','instructions','Instrucciones específicas del alcance','criteria',jsonb_build_array('Evidencia aceptada'),'owner_id','ed200000-0000-0000-0000-000000000001','due_date',current_date+10,'document_required',false));
select pg_temp.ok((select count(*)=45 from sgc_steps),'project can add scope-specific requirements without deleting baseline');
select pg_temp.ok((select (definition->'steps') ? 'X-ALCANCE' from sgc_gates where gate_code='G3'),'scope-specific step is required by the phase exit gate');
select pg_temp.denied($q$select sgc_project_action('ADD_STEP',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'phase_code','F1','step_code','GOV1','title','Override baseline','instructions','Not allowed','criteria',jsonb_build_array('Override'),'owner_id','ed200000-0000-0000-0000-000000000001','due_date',current_date+10))$q$,'custom steps cannot override baseline identifiers');
select set_config('request.jwt.claim.sub','ed200000-0000-0000-0000-000000000003',true);
select pg_temp.ok((select count(*)=1 from sgc_projects where project_code='SGC-TEST'),'authorized reader can consult project');
select pg_temp.denied($q$select sgc_project_action('REOPEN_PROJECT',jsonb_build_object('project_id',(select id from sgc_projects where project_code='SGC-TEST'),'note','Reader mutation'))$q$,'read-only user cannot mutate project');
reset role;update profiles set active=false where id='ed200000-0000-0000-0000-000000000003';set local role authenticated;
select pg_temp.ok((select count(*)=0 from sgc_projects),'inactive reader cannot read implementation data');
reset role;
select pg_temp.ok(not has_function_privilege('anon','public.sgc_project_action(text,jsonb)','EXECUTE'),'anonymous cannot invoke privileged project API');
select pg_temp.ok((select count(*)=0 from document_register where document_code in ('HC-SGC-IMP-001','HC-SGC-MC-01','HC-SGC-ARQ') and status<>'BORRADOR'),'adapted source documents are not automatically approved');
rollback;
